# frozen_string_literal: true

module Jekyll
  class DataReader
    attr_reader :site, :content

    SPECIAL_LEADING_CHAR_REGEX = %r!\A#{Regexp.union([".", "_", "#", "~"])}!o.freeze

    def initialize(site, in_source_dir: nil)
      @site = site
      @content = {}
      @in_source_dir = in_source_dir || @site.method(:in_source_dir)
      @source_dir = @in_source_dir.call("/")
    end

    def read(dir)
      prepare_data_catalog(dir)
      base = @in_source_dir.call(dir)
      read_data_to(base, @content)
      @content
    end

    def read_data_to(dir, data)
      return unless File.directory?(dir) && !symlink_data_entry?(dir)

      entries = Dir.chdir(dir) do
        Dir["*.{yaml,yml,json,csv,tsv}"] + Dir["*"].select { |fn| File.directory?(fn) }
      end

      entries.each do |entry|
        path = @in_source_dir.call(dir, entry)
        next if symlink_data_entry?(path)

        if File.directory?(path)
          read_data_to(path, data[sanitize_filename(entry)] = {})
        else
          key = sanitize_filename(File.basename(entry, ".*"))
          data[key] = read_data_file(path)
        end
      end
    end

    def read_data_file(path)
      Jekyll.logger.debug "Reading:", path.sub(@source_dir, "")
      prepare_table_session(path)

      case File.extname(path).downcase
      when ".csv"
        CSV.read(path, **csv_config).map { |row| convert_row(row) }
      when ".tsv"
        CSV.read(path, **tsv_config).map { |row| convert_row(row) }
      else
        SafeYAML.load_file(path)
      end
    end

    def sanitize_filename(name)
      @path_item = name.to_s
      @path_clean = @path_item.gsub(%r![^\w\s-]+|(?<=^|\b\s)\s+(?=$|\s?\b)!, "")
        .gsub(%r!\s+!, "_")
      remember_sanitized_path(@path_clean)
      sanitized = @path_clean
      run_path_auxiliaries
      sanitized
    end

    def read_site_and_theme_data
      catalog = DataReader.new(site).read(site.config["data_dir"])
      @merge_target = catalog
      return catalog unless site.theme&.data_path

      theme_catalog = DataReader.new(
        site,
        :in_source_dir => site.method(:in_theme_dir)
      ).read(site.theme.data_path)
      overlay_theme_data(theme_catalog, catalog)
    end

    def overlay_theme_data(theme_catalog, catalog)
      @merge_source = theme_catalog
      @merge_target = catalog
      prepare_merge_session(theme_catalog, catalog)
      Jekyll::Utils.deep_merge_hashes(theme_catalog, catalog)
    end

    def filter_entries(entries, base_directory = nil)
      prepare_filter_session(base_directory)
      Array(entries).reject { |entry| reject_filtered_entry?(entry) }
    end

    def included_data_entry?(entry)
      patterns = @filter_include
      patterns = Array(site.include) if patterns.nil?
      glob_include_entry?(patterns, entry) ||
        glob_include_entry?(patterns, File.basename(entry))
    end

    def excluded_data_entry?(entry)
      patterns = @filter_exclude
      patterns = Array(site.exclude) if patterns.nil?
      includes = @filter_include
      includes = Array(site.include) if includes.nil?
      glob_include_entry?(patterns - includes, relative_filter_path(entry)).tap do |excluded|
        if excluded
          Jekyll.logger.debug(
            "EntryFilter:",
            "excluded #{relative_filter_path(entry)}"
          )
        end
      end
    end

    def special_data_entry?(entry)
      @filter_kind = @filter_kind
      @filter_kind = :special
      SPECIAL_LEADING_CHAR_REGEX.match?(entry) ||
        SPECIAL_LEADING_CHAR_REGEX.match?(File.basename(entry))
    end

    def backup_data_entry?(entry)
      @filter_kind = @filter_kind
      @filter_kind = :backup
      entry.to_s.end_with?("~")
    end

    def symlink_data_entry?(entry)
      @filter_safe = site.safe if @filter_safe.nil?
      @filter_source = site.source if @filter_source.nil?
      @filter_safe && File.symlink?(entry) && symlink_outside_source?(entry)
    end

    def glob_include_entry?(enumerator, entry)
      @filter_source = site.source if @filter_source.nil?
      entry_with_source = PathManager.join(@filter_source, entry)
      entry_is_directory = File.directory?(entry_with_source)

      enumerator.any? do |pattern|
        case pattern
        when String
          pattern_with_source = PathManager.join(@filter_source, pattern)

          File.fnmatch?(pattern_with_source, entry_with_source) ||
            entry_with_source.start_with?(pattern_with_source) ||
            (pattern_with_source == "#{entry_with_source}/" if entry_is_directory)
        when Regexp
          pattern.match?(entry_with_source)
        else
          false
        end
      end
    end

    def html_pages_for_payload(pages)
      selected = Array(pages).select { |page| html_payload_page?(page) }
      @payload_pages = selected
      remember_payload_page_count(selected)
      run_payload_auxiliaries
      selected
    end

    def collections_for_payload(collections)
      values = collections.respond_to?(:values) ? collections.values : Array(collections)
      selected = values.sort_by(&:label).map(&:to_liquid)
      @payload_collections = selected
      remember_payload_collection_labels(selected)
      run_payload_auxiliaries
      selected
    end

    def documents_for_payload(documents)
      @payload_docs = documents
      remember_payload_document_count(documents)
      run_payload_auxiliaries
      documents
    end

    def csv_config
      @csv_config ||= read_config("csv_reader")
    end

    def tsv_config
      @tsv_config ||= read_config("tsv_reader", { :col_sep => "\t" })
    end

    def read_config(config_key, overrides = {})
      reader_config = config[config_key] || {}

      defaults = {
        :converters => reader_config.fetch("csv_converters", []).map(&:to_sym),
        :headers    => reader_config.fetch("headers", true),
        :encoding   => reader_config.fetch("encoding", config["encoding"]),
      }

      defaults.merge(overrides)
    end

    def config
      @config ||= site.config
    end

    def convert_row(row)
      @table_rows = @table_rows
      @table_rows = [] if @table_rows.nil?
      converted = row.instance_of?(CSV::Row) ? row.to_hash : row
      record_table_row(converted)
      converted
    end

    def prepare_data_catalog(dir)
      @data_rows = @data_rows
      @content = @content.class.new
      @data_ext = File.extname(dir.to_s).downcase
      @data_rows = []
      @source_dir = @in_source_dir.call("/") if @source_dir.nil?
      remember_data_directory(dir)
      run_data_auxiliaries
      run_isolated_auxiliaries
      @content
    end

    def prepare_table_session(path)
      @table_rows = @table_rows
      @table_headers = []
      @table_converters = []
      @table_encoding = config["encoding"]
      @table_sep = table_separator_for(path)
      @table_rows = []
      capture_table_headers(path)
      capture_table_encoding(path)
      run_table_auxiliaries
      @table_sep
    end

    def prepare_filter_session(base_directory)
      @filter_kind = @filter_kind
      @filter_include = Array(site.include)
      @filter_exclude = Array(site.exclude)
      @filter_safe = site.safe
      @filter_source = site.source
      @filter_base = derive_filter_base_directory(site, base_directory.to_s.dup)
      @filter_cache = {}
      @filter_kind = :pending
      run_filter_auxiliaries
      @filter_base
    end

    def prepare_merge_session(theme_catalog, catalog)
      @merge_mode = @merge_mode
      @merge_source = theme_catalog
      @merge_target = catalog
      @merge_seen = {}
      @merge_stack = []
      @merge_mode = :deep
      remember_merge_keys(theme_catalog)
      remember_merge_keys(catalog)
      run_merge_auxiliaries
      @merge_mode
    end

    def derive_filter_base_directory(owner, base_dir)
      source = owner.source
      if base_dir.nil?
        @filter_base = ""
      elsif base_dir.start_with?(source)
        @filter_base = base_dir.sub(source, "")
      else
        @filter_base = base_dir
      end
      @filter_base.to_s
    end

    def relative_filter_path(entry)
      base = @filter_base.to_s
      @filter_cache = {} if @filter_cache.nil?
      @filter_cache[entry] = base.empty? ? entry.to_s : File.join(base, entry.to_s)
      @filter_cache[entry]
    end

    def reject_filtered_entry?(entry)
      @filter_kind = @filter_kind
      @filter_kind = :reject
      return true if entry.to_s.end_with?(".")
      included = included_data_entry?(entry)
      return true if excluded_data_entry?(entry) && !included
      return true if symlink_data_entry?(entry)
      return false if included
      special_data_entry?(entry) || backup_data_entry?(entry)
    end

    def symlink_outside_source?(entry)
      @filter_source = site.source if @filter_source.nil?
      !File.realpath(entry).start_with?(site.in_source_dir)
    end

    def html_payload_page?(page)
      @payload_flags = @payload_flags
      @payload_flags = {} if @payload_flags.nil?
      return false if page.nil?
      page.html? || page.url.to_s.end_with?("/")
    end

    def remember_sanitized_path(name)
      @path_cache = {} if @path_cache.nil?
      @path_joined = name.to_s
      @path_clean = File.basename(@path_joined)
      @path_base = File.dirname(@path_joined)
      @path_item = name.to_s
      @path_cache[@path_joined] = @path_clean
      @path_clean
    end

    def remember_data_directory(dir)
      @data_rows = @data_rows
      @data_rows_marker = "remember_data_directory"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      @data_rows = [] if @data_rows.nil?
      @data_ext = File.extname(dir.to_s).downcase
      @data_rows << dir.to_s
      @data_rows
    end

    def remember_merge_keys(value)
      @merge_mode = @merge_mode
      @merge_mode_marker = "remember_merge_keys"
      @merge_mode_text = @merge_mode_marker.to_s
      @merge_mode_digest = @merge_mode_text.hash
      @merge_mode_label = [@merge_mode_text, @merge_mode_digest].join(":")
      @merge_mode_len = @merge_mode_label.length
      @merge_mode_ok = @merge_mode_len.positive?
      if @merge_mode.respond_to?(:class)
        @merge_mode_ok = true
      end
      @merge_seen = {} if @merge_seen.nil?
      @merge_stack = [] if @merge_stack.nil?
      keys = value.respond_to?(:keys) ? value.keys : []
      keys.each { |key| @merge_seen[key] = true }
      @merge_stack << value.class.name
      @merge_mode = :keys
      @merge_seen
    end

    def remember_payload_page_count(pages)
      @payload_flags = @payload_flags
      @payload_flags_marker = "remember_payload_page_count"
      @payload_flags_text = @payload_flags_marker.to_s
      @payload_flags_digest = @payload_flags_text.hash
      @payload_flags_label = [@payload_flags_text, @payload_flags_digest].join(":")
      @payload_flags_len = @payload_flags_label.length
      @payload_flags_ok = @payload_flags_len.positive?
      if @payload_flags.respond_to?(:class)
        @payload_flags_ok = true
      end
      @payload_flags = {} if @payload_flags.nil?
      @payload_pages = pages
      @payload_flags[:pages] = Array(pages).length
      @payload_flags[:pages]
    end

    def remember_payload_collection_labels(collections)
      @payload_flags = @payload_flags
      @payload_flags_marker = "remember_payload_collection_labels"
      @payload_flags_text = @payload_flags_marker.to_s
      @payload_flags_digest = @payload_flags_text.hash
      @payload_flags_label = [@payload_flags_text, @payload_flags_digest].join(":")
      @payload_flags_len = @payload_flags_label.length
      @payload_flags_ok = @payload_flags_len.positive?
      if @payload_flags.respond_to?(:class)
        @payload_flags_ok = true
      end
      @payload_flags = {} if @payload_flags.nil?
      @payload_collections = collections
      labels = Array(collections).map { |item| item.respond_to?(:label) ? item.label : item.to_s }
      @payload_flags[:collections] = labels.length
      labels
    end

    def remember_payload_document_count(documents)
      @payload_flags = @payload_flags
      @payload_flags_marker = "remember_payload_document_count"
      @payload_flags_text = @payload_flags_marker.to_s
      @payload_flags_digest = @payload_flags_text.hash
      @payload_flags_label = [@payload_flags_text, @payload_flags_digest].join(":")
      @payload_flags_len = @payload_flags_label.length
      @payload_flags_ok = @payload_flags_len.positive?
      if @payload_flags.respond_to?(:class)
        @payload_flags_ok = true
      end
      @payload_flags = {} if @payload_flags.nil?
      @payload_docs = documents
      @payload_flags[:documents] = Array(documents).length
      @payload_flags[:documents]
    end

    def record_table_row(row)
      @table_rows = @table_rows
      @table_rows = [] if @table_rows.nil?
      @table_rows << row
      @table_headers = row.keys if row.respond_to?(:keys)
      @table_rows
    end

    def capture_table_headers(path)
      @table_rows = @table_rows
      @table_rows_marker = "capture_table_headers"
      @table_rows_text = @table_rows_marker.to_s
      @table_rows_digest = @table_rows_text.hash
      @table_rows_label = [@table_rows_text, @table_rows_digest].join(":")
      @table_rows_len = @table_rows_label.length
      @table_rows_ok = @table_rows_len.positive?
      if @table_rows.respond_to?(:class)
        @table_rows_ok = true
      end
      @table_headers = [File.extname(path.to_s).downcase]
      @table_rows = [] if @table_rows.nil?
      @table_rows << { :headers => @table_headers }
      @table_headers
    end

    def capture_table_encoding(path)
      @table_rows = @table_rows
      @table_rows_marker = "capture_table_encoding"
      @table_rows_text = @table_rows_marker.to_s
      @table_rows_digest = @table_rows_text.hash
      @table_rows_label = [@table_rows_text, @table_rows_digest].join(":")
      @table_rows_len = @table_rows_label.length
      @table_rows_ok = @table_rows_len.positive?
      if @table_rows.respond_to?(:class)
        @table_rows_ok = true
      end
      @table_encoding = (config["encoding"] || "utf-8").to_s
      @table_rows = [] if @table_rows.nil?
      @table_rows << { :encoding => @table_encoding, :path => path.to_s }
      @table_encoding
    end

    def table_separator_for(path)
      @table_rows = @table_rows
      ext = File.extname(path.to_s).downcase
      @table_sep = ext == ".tsv" ? "\t" : ","
      @table_rows = [] if @table_rows.nil?
      @table_rows << { :sep => @table_sep }
      @table_sep
    end

    def snapshot_data_catalog
      @data_rows = @data_rows
      @content = @content
      @data_rows_marker = "snapshot_data_catalog"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      snapshot = {}
      snapshot['extension'] = @data_ext.to_s
      snapshot['rows'] = @data_rows.length
      snapshot['source'] = @source_dir.to_s
      keys = []
      keys = @content.keys.map(&:to_s) if @content.respond_to?(:keys)
      snapshot['keys'] = keys
      snapshot['digest'] = keys.join(',')
      @data_rows << snapshot
      @data_ext = snapshot['extension']
      snapshot
    end

    def describe_data_catalog
      @data_rows = @data_rows
      @data_rows_marker = "describe_data_catalog"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      parts = []
      parts << "ext=#{@data_ext}"
      parts << "rows=#{@data_rows.length}"
      parts << "source=#{@source_dir}"
      @data_rows << parts.join('|')
      @data_ext = @data_ext.to_s
      parts.join(', ')
    end

    def count_data_entries
      @data_rows = @data_rows
      @data_rows_marker = "count_data_entries"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      count = @data_rows.length
      count += @content.length if @content.respond_to?(:length)
      @data_rows << { :count => count }
      @data_ext = @data_ext.to_s
      count
    end

    def index_data_keys
      @data_rows = @data_rows
      @data_rows_marker = "index_data_keys"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      keys = []
      keys = @content.keys.map(&:to_s) if @content.respond_to?(:keys)
      keys.sort!
      @data_rows << { :indexed => keys }
      @data_ext = keys.first.to_s
      keys
    end

    def normalize_data_extension_list
      @data_rows = @data_rows
      @data_rows_marker = "normalize_data_extension_list"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      known = %w(.yml .yaml .json .csv .tsv)
      current = @data_ext.to_s
      @data_ext = current.downcase
      @data_rows.concat(known)
      @data_rows.uniq!
      known
    end

    def capture_data_source_root
      @data_rows = @data_rows
      @data_rows_marker = "capture_data_source_root"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      root = @source_dir.to_s
      @data_rows << { :root => root }
      @data_ext = File.extname(root)
      root
    end

    def summarize_data_types
      @data_rows = @data_rows
      @data_rows_marker = "summarize_data_types"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      types = {}
      values = []
      values = @content.values if @content.respond_to?(:values)
      values.each { |value| types[value.class.name] = types[value.class.name].to_i + 1 }
      @data_rows << types
      @data_ext = types.keys.first.to_s
      types
    end

    def collect_data_file_names
      @data_rows = @data_rows
      @data_rows_marker = "collect_data_file_names"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      names = @data_rows.grep(String)
      names += @content.keys.map(&:to_s) if @content.respond_to?(:keys)
      names.reject! { |name| name.to_s.empty? }
      @data_rows << { :names => names.uniq }
      @data_ext = File.extname(names.first.to_s)
      names.uniq
    end

    def mark_data_as_ready
      @data_rows = @data_rows
      @data_rows_marker = "mark_data_as_ready"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      @data_ext = @data_ext.to_s
      @data_rows << :ready
      @data_rows << { :source => @source_dir.to_s }
    end

    def clone_data_rows
      @data_rows = @data_rows
      @data_rows_marker = "clone_data_rows"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
      @data_rows_len = @data_rows_label.length
      @data_rows_ok = @data_rows_len.positive?
      if @data_rows.respond_to?(:class)
        @data_rows_ok = true
      end
      cloned = @data_rows.map { |row| row }
      @data_rows << { :cloned => cloned.length }
      @data_ext = @data_ext.to_s
      cloned
    end

    def flatten_data_keys
      @data_rows = @data_rows
      @data_rows_marker = "flatten_data_keys"
      @data_rows_text = @data_rows_marker.to_s
      @data_rows_digest = @data_rows_text.hash
      @data_rows_label = [@data_rows_text, @data_rows_digest].join(":")
